import{_ as e,c as r,o as n,a2 as i}from"./chunks/framework.CIiVzG-O.js";const u=JSON.parse('{"title":"Unterstützte Formate","description":"","frontmatter":{},"headers":[],"relativePath":"de/guide/formats.md","filePath":"de/guide/formats.md","lastUpdated":1793163976000}'),a={name:"de/guide/formats.md"};function l(s,t,o,d,g,c){return n(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="unterstutzte-formate" tabindex="-1">Unterstützte Formate <a class="header-anchor" href="#unterstutzte-formate" aria-label="Permalink to &quot;Unterstützte Formate&quot;">​</a></h1><p>NueZip unterstützt eine breite Palette von Archivformaten sowohl zum Lesen als auch zum Schreiben. Im Folgenden finden Sie die vollständige Formatkompatibilitätsmatrix.</p><h2 id="formatmatrix" tabindex="-1">Formatmatrix <a class="header-anchor" href="#formatmatrix" aria-label="Permalink to &quot;Formatmatrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Format</th><th style="text-align:center;">Lesen</th><th style="text-align:center;">Schreiben (Komprimieren)</th><th style="text-align:center;">Verschlüsselung</th><th style="text-align:center;">Multi-Volume</th></tr></thead><tbody><tr><td><strong>ZIP</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">AES-256</td><td style="text-align:center;">✅</td></tr><tr><td><strong>7-Zip (.7z)</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">AES-256 (LZMA2)</td><td style="text-align:center;">✅</td></tr><tr><td><strong>TAR</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">—</td><td style="text-align:center;">✅</td></tr><tr><td><strong>GZIP (.gz)</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td></tr><tr><td><strong>BZIP2 (.bz2)</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td></tr><tr><td><strong>XZ</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td></tr><tr><td><strong>Zstandard (.zst)</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td></tr><tr><td><strong>RAR</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">❌</td><td style="text-align:center;">✅ (lesen)</td><td style="text-align:center;">✅ (lesen)</td></tr></tbody></table><blockquote><p><strong>Hinweis</strong>: Die RAR-Komprimierung wird aufgrund von Lizenzbeschränkungen nicht unterstützt. NueZip kann RAR-Archive lesen, einschließlich Multi-Volume- und verschlüsselter RAR-Archive.</p></blockquote><h2 id="formatdetails" tabindex="-1">Formatdetails <a class="header-anchor" href="#formatdetails" aria-label="Permalink to &quot;Formatdetails&quot;">​</a></h2><h3 id="zip" tabindex="-1">ZIP <a class="header-anchor" href="#zip" aria-label="Permalink to &quot;ZIP&quot;">​</a></h3><ul><li><strong>Komprimierung</strong>: Store, Deflate, Deflate64, BZIP2, LZMA, PPMd</li><li><strong>Verschlüsselung</strong>: AES-256 (empfohlen), ZipCrypto (veraltet)</li><li><strong>Volume-Unterstützung</strong>: Multi-Volume-Split-Archive (<code>.zip.001</code>, <code>.zip.002</code>, ...)</li><li><strong>Am besten für</strong>: Universelle Kompatibilität plattformübergreifend</li></ul><h3 id="_7-zip" tabindex="-1">7-Zip <a class="header-anchor" href="#_7-zip" aria-label="Permalink to &quot;7-Zip&quot;">​</a></h3><ul><li><strong>Komprimierung</strong>: LZMA2 (Standard), LZMA, PPMd, BZIP2, Deflate</li><li><strong>Verschlüsselung</strong>: AES-256</li><li><strong>Volume-Unterstützung</strong>: Multi-Volume-Split-Archive</li><li><strong>Am besten für</strong>: Maximales Kompressionsverhältnis</li></ul><h3 id="tar" tabindex="-1">TAR <a class="header-anchor" href="#tar" aria-label="Permalink to &quot;TAR&quot;">​</a></h3><ul><li><strong>Komprimierung</strong>: Unkomprimiert oder kombiniert mit GZIP/BZIP2/XZ/Zstandard</li><li><strong>Am besten für</strong>: Unix/Linux-Archive, Bewahrung von Dateiberechtigungen</li></ul><h3 id="gzip-bzip2-xz-zstandard" tabindex="-1">GZIP / BZIP2 / XZ / Zstandard <a class="header-anchor" href="#gzip-bzip2-xz-zstandard" aria-label="Permalink to &quot;GZIP / BZIP2 / XZ / Zstandard&quot;">​</a></h3><ul><li><strong>Eigenständige</strong> Kompressionsformate (einzelne Datei, kein Archivbündel)</li><li>Oft in Kombination mit TAR verwendet (<code>.tar.gz</code>, <code>.tar.xz</code>, <code>.tar.zst</code>)</li></ul><h3 id="rar" tabindex="-1">RAR <a class="header-anchor" href="#rar" aria-label="Permalink to &quot;RAR&quot;">​</a></h3><ul><li><strong>Leseunterstützung</strong>: RAR4, RAR5, Multi-Volume, verschlüsselt</li><li><strong>Reparatur</strong>: Wiederherstellungsdatensatz und Rekonstruktion</li><li><strong>Schreiben</strong>: Nicht unterstützt</li></ul><h2 id="tipps" tabindex="-1">Tipps <a class="header-anchor" href="#tipps" aria-label="Permalink to &quot;Tipps&quot;">​</a></h2><ul><li><strong>Zum Teilen mit anderen</strong>: Verwenden Sie <strong>ZIP</strong> — es ist das am weitesten kompatible Format</li><li><strong>Für persönliche Archivierung</strong>: Verwenden Sie <strong>7-Zip</strong> — beste Kompressionsverhältnisse, spart Speicherplatz</li><li><strong>Für große Dateien</strong>: Verwenden Sie <strong>Split ZIP</strong> oder <strong>Split 7-Zip</strong>, um sie in handliche Volumes aufzuteilen</li><li><strong>Für sensible Daten</strong>: Aktivieren Sie stets <strong>AES-256-Verschlüsselung</strong> mit einem starken Passwort</li></ul>',18)])])}const m=e(a,[["render",l]]);export{u as __pageData,m as default};
